import {
  StyledComparison,
  StyledComparisonNumber,
} from 'components/BigNumber/BigNumber.styles';
import {
  BigNumberAlignment,
  BigNumberData,
  BigNumberSize,
  BigNumberTrendColors,
} from 'components/BigNumber/types';
import { getTrendDisplayColor } from 'components/BigNumber/utils';

import { StyledBigNumberComparisonContainer } from '../BigNumberContent/BigNumberContent.styles';

interface BigNumberComparisonProps {
  item: BigNumberData;
  size?: BigNumberSize;
  dataTestId?: string;
  preserveSpace?: boolean;
  alignment?: BigNumberAlignment;
  trendColors?: BigNumberTrendColors;
}

export const BigNumberComparison = ({
  item,
  size,
  dataTestId,
  preserveSpace = false,
  alignment,
  trendColors,
}: BigNumberComparisonProps) => {
  const comparison = item.comparison;
  const hasComparisonValue = !!comparison?.value;

  if (!preserveSpace && !hasComparisonValue) return null;

  return (
    <StyledBigNumberComparisonContainer
      data-testid={dataTestId}
      $preserveSpace={preserveSpace && !hasComparisonValue}
      $alignment={alignment}
    >
      {hasComparisonValue && comparison && (
        <>
          {comparison.number?.value ? (
            <StyledComparisonNumber
              $size={size}
              style={{
                color: getTrendDisplayColor(comparison.number, trendColors),
              }}
            >
              {comparison.number.value}
              {comparison.number.measure}
            </StyledComparisonNumber>
          ) : (
            <StyledComparison $size={size} style={{ fontWeight: '400' }}>
              {comparison.label}
            </StyledComparison>
          )}
          <StyledComparison $size={size} style={{ fontWeight: '500' }}>
            {comparison.number?.value && (
              <StyledComparison $size={size} style={{ fontWeight: '400' }}>
                {comparison.label}
              </StyledComparison>
            )}{' '}
            {comparison.value}
          </StyledComparison>
        </>
      )}
    </StyledBigNumberComparisonContainer>
  );
};
